function icon(n){return`<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[n]||paths.help}"/></svg></span>`}
function button(label,action,args={},style='',ico=''){return`<button class="btn ${style}" data-action="${action}" data-args="${h(encodeURIComponent(JSON.stringify(args)))}">${ico?icon(ico):''}<span>${h(label)}</span></button>`}
const empty=(message,ico='calendar')=>`<div class="empty">${icon(ico)}${h(message)}</div>`;
const tag=(label,color='')=>`<span class="tag ${color}">${h(label)}</span>`;
const storage={get(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
const S={mode:'live',page:'overview',date:localDate(),data:null,base:null,user:{id:'guest',role:'guest',name:'Посетитель'},users:[],versions:[],revision:0,token:'',groupId:storage.get('uf.group','g-main'),subgroup:storage.get('uf.subgroup','А'),teacherId:'',scope:'group',search:'',weekView:false,taskFilter:'all',catalog:'groups',online:false,busy:false,demoFull:null,demoUsers:clone(DEMO_USERS),epoch:0};
const nav=[['overview','Обзор','home'],['schedule','Расписание','calendar'],['tasks','Задания','task'],['notifications','Уведомления','bell'],['requests','Запросы','request'],['catalogs','Справочники','layers'],['history','История','history'],['accounts','Аккаунты','users'],['guide','Инструкция','help']];
const isAdmin=()=>S.user.role==='admin',isTeacher=()=>S.user.role==='teacher',canWrite=()=>isAdmin()||isTeacher();
const name=(kind,id,unknown='Не назначено')=>S.data?.[kind]?.find(x=>x.id===id)?.name||unknown;
const niceDate=(date,long=false)=>new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:long?'long':'short',...(long?{weekday:'long'}:{})}).format(new Date(date+'T12:00:00Z'));
const myKey=key=>'uf.'+key+'.'+S.mode+'.'+S.user.id;
function viewedGroup(){return S.data?.groups.find(g=>g.id===S.groupId)||S.data?.groups[0]}
function scopedLessons(date=S.date){return occurrences(S.data,date).filter(l=>{const group=S.scope==='teacher'||isTeacher()?(!S.teacherId||l.teacherId===S.teacherId):l.groupId===S.groupId&&(S.subgroup==='all'||l.subgroup==='all'||l.subgroup===S.subgroup);const query=[name('subjects',l.subjectId),name('teachers',l.teacherId,''),name('rooms',l.roomId,''),name('groups',l.groupId)].join(' ').toLowerCase();return group&&(!S.search||query.includes(S.search.toLowerCase()))})}
function unread(){const read=new Set(storage.get(myKey('read'),[]));return(S.data?.announcements||[]).filter(n=>!read.has(n.id)).length}
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4200)}
async function api(action,extra={}){const r=await fetch(API+'/functions/v1/uniflow-api',{method:'POST',headers:{'Content-Type':'application/json',apikey:KEY},body:JSON.stringify({action,token:S.token,...extra}),signal:AbortSignal.timeout(20000)});let data;try{data=await r.json()}catch{throw Error('Сервер не ответил. Попробуй ещё раз.')}if(!r.ok){const e=Error(data.error||'Ошибка сервера');e.status=r.status;throw e}return data}
function install(result){S.data=result.data;S.revision=result.revision;S.user=result.user;S.users=result.users||[];S.versions=result.versions||[];S.online=true;if(S.user.role==='student'){S.groupId=S.user.groupId;S.subgroup=S.user.subgroup}if(isTeacher()){S.scope='teacher';S.teacherId=S.user.teacherId}if(!S.data.groups.some(g=>g.id===S.groupId))S.groupId=S.data.groups[0]?.id||'';if(!S.data.groups.find(g=>g.id===S.groupId)?.subgroups.includes(S.subgroup)&&S.subgroup!=='all')S.subgroup=S.data.groups.find(g=>g.id===S.groupId)?.subgroups[0]||''}
let refreshing=false;
async function refresh(silent=false){if(S.mode!=='live'||refreshing||document.hidden)return;refreshing=true;const epoch=S.epoch;try{const result=await api('state',{groupId:S.groupId,subgroup:S.subgroup});if(S.mode==='live'&&epoch===S.epoch){install(result);render();if($('modal').open&&$('modal').dataset.revision&&Number($('modal').dataset.revision)!==S.revision){const e=$('form-error');if(e)e.textContent='Данные изменились. Закрой и открой форму заново перед сохранением.'}}}catch(e){if(epoch===S.epoch&&S.mode==='live'){S.online=false;if(e.status===401){S.token='';S.user={id:'guest',role:'guest',name:'Посетитель'};S.data=null;setTimeout(()=>refresh(),100)}if(!silent)toast(e.message);render()}}finally{refreshing=false}}
let channel;
function connectRealtime(){if(!window.supabase)return;const client=window.supabase.createClient(API,KEY,{auth:{persistSession:false,autoRefreshToken:false}});channel=client.channel('uniflow-signal').on('postgres_changes',{event:'UPDATE',schema:'public',table:'uf_signal',filter:'id=eq.1'},()=>refresh(true)).subscribe(status=>{if(status==='SUBSCRIBED')refresh(true)})}
function applyDemo(){install({data:visible(S.demoFull,S.user),revision:S.revision,user:S.user,users:isAdmin()?S.demoUsers:isTeacher()?S.demoUsers.filter(u=>u.role==='student'&&S.demoFull.lessons.some(l=>l.teacherId===S.user.teacherId&&l.groupId===u.groupId&&(l.subgroup==='all'||u.subgroup===l.subgroup))):[],versions:S.versions});storage.set('uf.demo',{data:S.demoFull,users:S.demoUsers,revision:S.revision,versions:S.versions});render()}
async function enterDemo(role='student'){if(!S.base){toast('Загружаем пример…');return}S.epoch++;S.mode='demo';S.token='';const saved=storage.get('uf.demo',null);S.demoFull=saved?.data||makeDemo(S.base);S.demoUsers=saved?.users||clone(DEMO_USERS);S.revision=saved?.revision||1;S.versions=saved?.versions||[];S.user=clone(S.demoUsers.find(u=>u.id===({student:'demo-student-a',teacher:'demo-teacher',admin:'demo-admin'}[role]))||DEMO_USERS[0]);S.groupId='g-main';S.subgroup='А';S.teacherId='';S.scope='group';S.page='overview';S.search='';applyDemo();history.replaceState(null,'',location.pathname+'?demo='+role)}
async function leaveDemo(){S.mode='live';S.epoch++;S.data=null;S.user={id:'guest',role:'guest',name:'Посетитель'};S.versions=[];S.teacherId='';S.scope='group';S.page='overview';history.replaceState(null,'',location.pathname);render();await refresh()}
async function act(op,payload,expected=S.revision){if(S.busy)throw Error('Дождись сохранения');if(S.mode==='live'&&!S.online)throw Error('Нет связи с сервером. Изменения не отправлены.');S.busy=true;try{if(S.mode==='demo'){if(expected!==S.revision)throw Error('Данные изменились. Открой форму заново.');const before=clone(S.demoFull),result=mutate(S.demoFull,S.user,op,payload);S.versions.unshift({revision:S.revision,actor:S.user.name,reason:result.summary,created_at:new Date().toISOString(),data:before});S.versions=S.versions.slice(0,30);S.demoFull=result.data;S.revision++;applyDemo()}else{install(await api('mutate',{op,payload,revision:expected}));render()}toast('Сохранено'+(S.mode==='demo'?' в демо-песочнице':' для участников'));}catch(e){if(e.status===409)await refresh(true);throw e}finally{S.busy=false}}
function allowedPage(page){if(page==='attendance')return false;if(['history','accounts'].includes(page))return isAdmin();if(page==='requests')return canWrite();return true}
function shell(content){const userLabel=S.user.role==='guest'?'Открытое расписание':S.user.name;return`<div class="layout"><aside class="sidebar"><div class="brand">UniFlow</div><div class="brand-sub">Учёба в одном ритме</div><nav class="nav" aria-label="Разделы">${nav.filter(([p])=>allowedPage(p)).map(([p,t,i])=>`<button data-page="${p}" class="${S.page===p?'active':''}" ${S.page===p?'aria-current="page"':''}>${icon(i)}${t}${p==='notifications'&&unread()?`<span class="count">${unread()}</span>`:''}${p==='requests'&&S.data?.requests.filter(r=>r.status==='pending').length?`<span class="count">${S.data.requests.filter(r=>r.status==='pending').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><b>UniFlow · beta 2.0</b><br>Автор: Азат Араппаев<br>Казахстан · UTC+5</div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">${icon('home')}Рабочее пространство</span><label class="global-search">${icon('search')}<input id="global-search" type="search" value="${h(S.search)}" placeholder="Поиск по расписанию…" aria-label="Поиск по расписанию"></label><div class="top-actions">${button('Демо ролей','demo',{},'','flask')}${button(S.user.role==='guest'?'Войти':'Кабинет',S.user.role==='guest'?'login':'profile',{},'','users')}<button class="avatar" data-action="profile" aria-label="Открыть профиль">${h(S.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</button></div></header><main class="main" id="main"><div class="heading"><div><h1>${headingTitle()}</h1><p>${h(userLabel)} · ${h(ROLES[S.user.role])}${S.mode==='demo'?' · пример роли':''}</p></div><div class="heading-actions">${S.mode==='demo'?roleSwitcher():button('Инструкция','page',{page:'guide'},'ghost','help')}${S.page==='schedule'&&isAdmin()?button('Добавить занятие','lesson',{},'primary','plus'):''}</div></div>${S.mode==='demo'?`<div class="demo-banner">${icon('flask')}<div><strong>Демо-песочница.</strong> Пробуй все роли. Изменения не затрагивают настоящее расписание.</div><div class="right">${button('Сбросить пример','resetDemo',{},'tiny')}${button('Настоящий сайт','leaveDemo',{},'tiny')}</div></div>`:''}${content}<div class="sync ${S.online?'':'offline'}" role="status">${S.mode==='demo'?'Демо-данные сохраняются в этом браузере':S.online?'Подключено · общие изменения обновляются автоматически':'Нет связи · запись временно недоступна'}</div><footer class="footer"><span>UniFlow · меньше суеты, больше ясности</span><span>Бета-версия · время Казахстана · UTC+5</span></footer></main></div></div>`}
function headingTitle(){return({overview:'Всё для учебной недели.',schedule:'Твоё расписание.',tasks:'Задания и дедлайны.',notifications:'Важное — в одном месте.',requests:'Переносы без путаницы.',attendance:'Журнал посещаемости.',catalogs:'Учебное пространство.',history:'История изменений.',accounts:'Люди и права доступа.',guide:'Как работает UniFlow.'})[S.page]||'UniFlow'}
function roleSwitcher(){return`<div class="role-switch" aria-label="Демонстрационная роль">${['student','teacher','admin'].map(r=>`<button data-action="demoRole" data-role="${r}" class="${S.user.role===r?'active':''}" aria-pressed="${S.user.role===r}">${ROLES[r]}</button>`).join('')}</div>`}
function optionList(items,value,label='name',blank=''){return(blank!==false?`<option value="">${h(blank||'Не назначено')}</option>`:'')+items.map(i=>`<option value="${h(i.id)}" ${i.id===value?'selected':''}>${h(i[label])}</option>`).join('')}
function filters(){const group=viewedGroup(),locked=S.user.role==='student';return`<div class="toolbar">${!isTeacher()?`<label class="field-inline">Режим<select data-filter="scope"><option value="group" ${S.scope==='group'?'selected':''}>По группе</option><option value="teacher" ${S.scope==='teacher'?'selected':''}>По преподавателю</option></select></label>`:''}${S.scope==='teacher'||isTeacher()?`<label class="field-inline">Преподаватель<select data-filter="teacherId" ${isTeacher()?'disabled':''}>${optionList(S.data.teachers,S.teacherId,'name','Все преподаватели')}</select></label>`:`<label class="field-inline">Группа<select data-filter="groupId" ${locked?'disabled':''}>${optionList(S.data.groups,S.groupId,'name',false)}</select></label><label class="field-inline">Подгруппа<select data-filter="subgroup" ${locked?'disabled':''}>${['all',...(group?.subgroups||[])].map(g=>`<option value="${h(g)}" ${g===S.subgroup?'selected':''}>${g==='all'?'Все подгруппы':h(g)}</option>`).join('')}</select></label>`}<span class="spacer"></span>${button('Назад','week',{offset:-7},'btn-square','back')}<span class="small muted">${h(niceDate(monday(S.date)))} — ${h(niceDate(addDays(monday(S.date),6)))} · ${isoWeek(S.date)%2?'нечётная':'чётная'}</span>${button('Вперёд','week',{offset:7},'btn-square','arrow')}${button('Сегодня','today',{},'')}${button(S.weekView?'День':'Неделя','toggleWeek',{},'')}</div>`}
function dayButtons(){return`<div class="days" aria-label="Дни недели">${SHORT.map((d,i)=>{const date=addDays(monday(S.date),i);return`<button data-action="day" data-date="${date}" class="${date===S.date?'active':''} ${date===localDate()?'today':''}" aria-label="${DAYS[i]}" aria-pressed="${date===S.date}">${d}</button>`}).join('')}</div>`}
function lessonTable(list,date,editable=true){if(!list.length)return empty(S.search?'По этому запросу занятий нет':'На этот день занятий нет.');const now=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Qyzylorda',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());return`<div class="table-scroll"><table class="table schedule-table"><thead><tr><th>ВРЕМЯ</th><th>ДИСЦИПЛИНА</th><th>ПРЕПОДАВАТЕЛЬ</th><th>АУДИТОРИЯ</th>${editable&&canWrite()?'<th>ДЕЙСТВИЯ</th>':''}</tr></thead><tbody>${list.map(l=>`<tr class="${l.cancelled?'cancelled':date===localDate()&&l.start<=now&&l.end>now?'current':''}"><td class="time-cell">${h(l.start)}–${h(l.end)}<small>${time(l.end)-time(l.start)} мин</small></td><td><strong>${h(name('subjects',l.subjectId))}</strong><div class="subline">${h(l.type)} · ${h(name('groups',l.groupId))} · ${l.subgroup==='all'?'А и Б':h(l.subgroup)} ${l.week!=='all'?'· '+(l.week==='odd'?'нечётная':'чётная'):''}</div>${l.cancelled?tag('Отменено','red'):l.exception?tag('Перенос на эту дату','amber'):''}</td><td>${h(name('teachers',l.teacherId))}</td><td>${tag(name('rooms',l.roomId,'Не указана'))}</td>${editable&&canWrite()?`<td><div class="actions">${isAdmin()?button('Изменить','lesson',{id:l.id},'tiny','edit')+button('По дате','exception',{id:l.id,date},'tiny'):l.teacherId===S.user.teacherId?button('Перенос','request',{id:l.id,date},'tiny','request'):''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function weekGrid(){return`<div class="week-grid">${SHORT.map((label,i)=>{const date=addDays(monday(S.date),i);return`<div class="week-col"><h3>${label} · ${niceDate(date)}</h3>${scopedLessons(date).map(l=>`<div class="week-lesson ${l.cancelled?'cancelled':''}" data-action="day" data-date="${date}" tabindex="0" role="button"><span>${h(l.start)}–${h(l.end)}</span><strong>${h(name('subjects',l.subjectId))}</strong><small>${h(name('rooms',l.roomId))} · ${l.subgroup==='all'?'А и Б':h(l.subgroup)}</small></div>`).join('')||'<div class="empty">Нет занятий</div>'}</div>`}).join('')}</div>`}
function schedule(){return filters()+`<div class="toolbar">${button('Календарь .ics','exportIcs',{},'','download')}${button('Печать','print',{},'','print')}${button('Поделиться','share',{},'','share')}${isAdmin()?button('Экспорт JSON','exportJson',{},'','download')+button('Импорт JSON','import',{},''):''}</div>`+(S.weekView?weekGrid():`<section class="panel"><div class="panel-head"><h2>${icon('calendar')}Расписание на неделю</h2>${dayButtons()}</div><div class="day-caption"><span>${h(niceDate(S.date,true))}</span><span>${scopedLessons().length} занятий</span></div>${lessonTable(scopedLessons(),S.date)}</section>`)}
function dashboard(){const today=localDate();const now=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Qyzylorda',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());const list=scopedLessons(today).filter(l=>!l.cancelled),current=list.find(l=>l.start<=now&&l.end>now);let next,nextDate;for(let n=0;n<15;n++){const date=addDays(today,n);const lesson=scopedLessons(date).find(l=>!l.cancelled&&(n>0||l.start>now));if(lesson){next=lesson;nextDate=date;break}}const tasks=S.data.tasks.slice().sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3);const notices=S.data.announcements.slice(0,3);
 const week=Array.from({length:7},(_,i)=>scopedLessons(addDays(monday(S.date),i)).filter(l=>!l.cancelled)).flat();
 return`${isAdmin()?`<div class="stats"><div class="stat"><small>ГРУППЫ</small><strong>${S.data.groups.length}</strong><span>в учебном пространстве</span></div><div class="stat"><small>ЗАНЯТИЯ НЕДЕЛИ</small><strong>${week.length}</strong><span>по выбранному фильтру</span></div><div class="stat"><small>УЧЕБНЫЕ ЧАСЫ</small><strong>${(week.reduce((n,l)=>n+time(l.end)-time(l.start),0)/60).toFixed(1)}</strong><span>астрономические часы</span></div><div class="stat"><small>ОЖИДАЮТ РЕШЕНИЯ</small><strong>${S.data.requests.filter(r=>r.status==='pending').length}</strong><span>запросов на перенос</span></div></div>`:''}<div class="dashboard"><div><div class="hero-grid"><section class="panel live">${tag(current?'Текущее занятие':'Сейчас нет занятий')}<h2>${h(current?name('subjects',current.subjectId):'Время выдохнуть.')}</h2><div class="class-meta">${current?`<span>${icon('clock')}${h(current.start)}–${h(current.end)}</span><span>${icon('pin')}${h(name('rooms',current.roomId))}</span>`:'Пары определяются по времени Казахстана'}</div></section><section class="panel next">${tag('Следующее занятие')}<h2>${h(next?name('subjects',next.subjectId):'Свободное время')}</h2><div class="class-meta">${next?`${h(niceDate(nextDate))} · ${h(next.start)}–${h(next.end)}<br>${h(name('rooms',next.roomId))}`:'В ближайшие две недели занятий нет'}</div></section></div><section class="panel"><div class="panel-head"><h2>${icon('calendar')}Твоя учебная неделя</h2>${dayButtons()}</div><div class="day-caption"><span>${h(niceDate(S.date,true))}</span><span>${h(S.scope==='teacher'?name('teachers',S.teacherId,'Все преподаватели'):name('groups',S.groupId))} · ${h(S.subgroup==='all'?'А и Б':S.subgroup)}</span></div>${lessonTable(scopedLessons(),S.date)}</section><div class="notice-info section-space row">${icon('users')}<span>${S.mode==='demo'?'Примеры участников: Алексей — студент, Айдана — преподаватель. Переключай роли, чтобы увидеть результат своих действий.':'Студенты видят свои группы, преподаватели — свои пары, администратор управляет назначениями.'}</span>${button('Открыть расписание','page',{page:'schedule'},'tiny')}</div>${isAdmin()?workload():''}</div><aside class="stack"><section class="panel"><div class="panel-head"><h2>${icon('task')}Ближайшие задания</h2></div>${tasks.length?`<div class="list">${tasks.map(t=>`<div class="list-item">${icon('request')}<div><h3>${h(t.title)}</h3><p>До ${niceDate(t.due)} · ${h(name('subjects',t.subjectId))}</p></div></div>`).join('')}</div>`:empty('Новых заданий пока нет','task')}</section><section class="panel"><div class="panel-head"><h2>${icon('bell')}Изменения</h2></div>${notices.length?`<div class="list">${notices.map(n=>`<div class="list-item">${icon('bell')}<div><h3>${h(n.title)}</h3><p>${h(n.body.slice(0,140))}</p></div></div>`).join('')}</div>`:empty('Здесь появятся объявления и изменения','bell')}</section><section class="panel panel-pad"><h3>Быстрые действия</h3><div class="row section-space">${button('Мои задания','page',{page:'tasks'},'tiny','task')}${canWrite()?button('Запрос переноса','request',{},'tiny','request'):button('Как пользоваться','page',{page:'guide'},'tiny','help')}</div></section></aside></div>`}
function workload(){return`<section class="panel section-space"><div class="panel-head"><h2>Нагрузка преподавателей</h2>${button('Свободные аудитории','freeRooms',{},'tiny','search')}</div><div class="table-scroll"><table class="table"><thead><tr><th>ПРЕПОДАВАТЕЛЬ</th><th>ПАР / НЕДЕЛЮ</th><th>ЧАСЫ</th></tr></thead><tbody>${S.data.teachers.map(t=>{const ls=Array.from({length:7},(_,i)=>occurrences(S.data,addDays(monday(S.date),i))).flat().filter(l=>!l.cancelled&&l.teacherId===t.id);return`<tr><td>${h(t.name)}</td><td>${ls.length}</td><td>${(ls.reduce((n,l)=>n+time(l.end)-time(l.start),0)/60).toFixed(1)}</td></tr>`}).join('')}</tbody></table></div>${!S.data.teachers.length?empty('Добавь преподавателей и назначь им пары'):''}</section>`}
function tasks(){const done=new Set(storage.get(myKey('tasks'),[])),today=localDate();const list=S.data.tasks.filter(t=>S.taskFilter==='done'?done.has(t.id):S.taskFilter==='overdue'?t.due<today&&!done.has(t.id):S.taskFilter==='open'?!done.has(t.id):true).sort((a,b)=>a.due.localeCompare(b.due));return`<div class="toolbar"><div class="tabs">${[['all','Все'],['open','К выполнению'],['overdue','Просрочено'],['done','Готово']].map(([v,t])=>`<button data-action="taskFilter" data-value="${v}" class="${S.taskFilter===v?'active':''}">${t}</button>`).join('')}</div><span class="spacer"></span>${canWrite()?button('Новое задание','task',{},'primary','plus'):''}</div><section class="panel">${list.length?list.map(t=>`<article class="task ${done.has(t.id)?'done':''}"><label class="check"><input type="checkbox" data-task-check="${h(t.id)}" ${done.has(t.id)?'checked':''} aria-label="Отметить задание выполненным"></label><div class="grow"><h3>${h(t.title)}</h3><p>${h(t.description)}</p><div class="task-meta">${tag('До '+niceDate(t.due),t.due<today&&!done.has(t.id)?'red':'')}${tag(name('subjects',t.subjectId))}${tag(name('groups',t.groupId)+' · '+(t.subgroup==='all'?'А и Б':t.subgroup))}</div></div>${canWrite()?`<div class="actions">${button('Изменить','task',{id:t.id},'tiny','edit')}${button('Удалить','deleteTask',{id:t.id},'tiny danger','trash')}</div>`:''}</article>`).join(''):empty('Заданий по этому фильтру пока нет','task')}</section><p class="small muted section-space">Отметки выполнения — личные, сохраняются на этом устройстве. Это не отправка работы преподавателю.</p>`}
function notifications(){const read=new Set(storage.get(myKey('read'),[]));return`<div class="toolbar"><span class="small muted">${unread()} непрочитанных · уведомления внутри сайта</span><span class="spacer"></span>${button('Прочитать все','readAll',{},'','check')}${canWrite()?button('Объявление','announcement',{},'primary','plus'):''}</div><section class="panel">${S.data.announcements.length?S.data.announcements.map(n=>`<article class="notice ${read.has(n.id)?'':'unread'}"><div class="notice-top"><h3>${h(n.title)}</h3><small>${h(niceDate(n.createdAt.slice(0,10)))}</small></div><p>${h(n.body)}</p>${tag(n.groupId?name('groups',n.groupId):n.teacherId?name('teachers',n.teacherId):'Получатели: '+n.roles.map(r=>ROLES[r]).join(', '))}${!read.has(n.id)?`<div style="margin-top:12px">${button('Прочитано','read',{id:n.id},'tiny')}</div>`:''}</article>`).join(''):empty('Нет уведомлений для твоей роли','bell')}</section>`}
function requests(){return`<div class="toolbar"><span class="small muted">${isAdmin()?'Решение администратора обновляет расписание по дате':'Запрос не меняет расписание до утверждения'}</span><span class="spacer"></span>${button('Запросить перенос','request',{},'primary','plus')}</div><section class="panel">${S.data.requests.length?S.data.requests.map(r=>{const l=S.data.lessons.find(l=>l.id===r.lessonId);return`<article class="notice"><div class="notice-top"><h3>${h(name('subjects',l?.subjectId,'Удалённая пара'))}</h3>${tag(({pending:'Ожидает решения',approved:'Согласовано',rejected:'Отклонено'})[r.status],r.status==='approved'?'green':r.status==='rejected'?'red':'amber')}</div><p>${h(r.reason)}</p><div class="small muted section-space">${h(name('teachers',r.teacherId))} · ${niceDate(r.date)} · ${h(r.start)}–${h(r.end)} · ${h(name('rooms',r.roomId))}</div>${r.response?`<p>Ответ: ${h(r.response)}</p>`:''}${isAdmin()&&r.status==='pending'?`<div class="row section-space">${button('Согласовать','decide',{id:r.id,status:'approved'},'primary tiny','check')}${button('Отклонить','decide',{id:r.id,status:'rejected'},'danger tiny','close')}</div>`:''}</article>`}).join(''):empty('Запросов пока нет','request')}</section>`}
function attendance(){if(!canWrite()){const rows=S.data.attendance;return`<section class="panel"><div class="panel-head"><h2>Моя посещаемость</h2></div>${rows.length?`<div class="list">${rows.map(a=>`<div class="list-item"><div><h3>${h(name('subjects',S.data.lessons.find(l=>l.id===a.lessonId)?.subjectId))}</h3><p>${niceDate(a.date)}</p></div><span class="end">${tag(attStatus(a.status),a.status==='absent'?'red':'green')}</span></div>`).join('')}</div>`:empty(S.user.role==='guest'?'Войди в аккаунт студента, чтобы видеть свою посещаемость':'Преподаватель пока не выставил отметки','book')}</section>`}const lessons=occurrences(S.data,S.date).filter(l=>!l.cancelled&&(isAdmin()||l.teacherId===S.user.teacherId));const lesson=lessons.find(l=>l.id===S.attendanceId)||lessons[0];if(lesson)S.attendanceId=lesson.id;const students=S.users.filter(u=>u.role==='student'&&u.active&&u.groupId===lesson?.groupId&&(lesson.subgroup==='all'||u.subgroup===lesson.subgroup));return`<div class="toolbar"><label class="field-inline">Дата<input type="date" id="attendance-date" value="${S.date}"></label><label class="field-inline">Занятие<select id="attendance-lesson">${lessons.map(l=>`<option value="${h(l.id)}" ${l.id===lesson?.id?'selected':''}>${h(l.start+' · '+name('subjects',l.subjectId)+' · '+name('groups',l.groupId))}</option>`).join('')}</select></label><span class="spacer"></span>${button('Экспорт CSV','attendanceCsv',{},'','download')}</div><section class="panel"><div class="panel-head"><h2>${lesson?h(name('groups',lesson.groupId)):'На эту дату нет занятий'}</h2></div>${students.length?`<div class="table-scroll"><table class="table"><thead><tr><th>СТУДЕНТ</th><th>ПОДГРУППА</th><th>ОТМЕТКА</th></tr></thead><tbody>${students.map(u=>{const mark=S.data.attendance.find(a=>a.studentId===u.id&&a.lessonId===lesson.id&&a.date===S.date)?.status||'';return`<tr><td>${h(u.name)}</td><td>${h(u.subgroup)}</td><td><select data-attendance="${h(u.id)}" aria-label="Посещаемость ${h(u.name)}"><option value="">Не отмечен</option>${['present','late','absent','excused'].map(s=>`<option value="${s}" ${s===mark?'selected':''}>${attStatus(s)}</option>`).join('')}</select></td></tr>`}).join('')}</tbody></table></div>`:empty('Для этой пары нет активных аккаунтов студентов. Администратор может создать их в разделе «Аккаунты».','users')}</section>`}
const attStatus=s=>({present:'Присутствует',late:'Опоздал',absent:'Отсутствует',excused:'Уважительная причина'})[s]||'Не отмечен';
function catalogs(){const kind=S.catalog;const labels={groups:'Группы',teachers:'Преподаватели',subjects:'Предметы',rooms:'Аудитории'};return`<div class="toolbar"><div class="tabs">${Object.entries(labels).map(([k,t])=>`<button data-action="catalogTab" data-kind="${k}" class="${k===kind?'active':''}">${t}</button>`).join('')}</div><span class="spacer"></span>${kind==='rooms'?button('Найти свободную','freeRooms',{},'','search'):''}${isAdmin()?button('Добавить','catalog',{entity:kind},'primary','plus'):''}</div><section class="panel"><div class="table-scroll"><table class="table"><thead><tr><th>НАЗВАНИЕ</th><th>ПОДРОБНОСТИ</th>${isAdmin()?'<th>ДЕЙСТВИЯ</th>':''}</tr></thead><tbody>${S.data[kind].map(x=>`<tr><td><strong>${h(x.name)}</strong></td><td>${h(kind==='groups'?'Подгруппы: '+x.subgroups.join(', '):kind==='teachers'?x.subjects.map(id=>name('subjects',id)).join(', '):kind==='rooms'?'Мест: '+x.capacity:'Учебная дисциплина')}</td>${isAdmin()?`<td><div class="actions">${button('Изменить','catalog',{entity:kind,id:x.id},'tiny','edit')}${button('Удалить','deleteCatalog',{entity:kind,id:x.id},'tiny danger','trash')}</div></td>`:''}</tr>`).join('')}</tbody></table></div>${!S.data[kind].length?empty('Справочник пока пуст','layers'):''}</section>`}
function historyPage(){return`<div class="notice-info">Сохраняются последние 30 версий. Откат восстанавливает расписание, задания, объявления и журнал. Аккаунты и пароли не откатываются.</div><section class="panel section-space"><div class="panel-head"><h2>Версии пространства</h2></div>${S.versions.length?`<div class="list">${S.versions.map(v=>`<div class="list-item">${icon('history')}<div><h3>Версия ${v.revision} · ${h(v.reason)}</h3><p>${h(v.actor)} · ${h(new Date(v.created_at).toLocaleString('ru-RU'))}</p></div><div class="end">${button('Восстановить','rollback',{revision:v.revision},'tiny')}</div></div>`).join('')}</div>`:empty('После первого изменения здесь появится версия для восстановления','history')}</section><section class="panel section-space"><div class="panel-head"><h2>Журнал действий</h2></div><div class="list">${S.data.history.map(e=>`<div class="list-item"><div><h3>${h(e.summary)}</h3><p>${h(e.actor)} · ${h(new Date(e.at).toLocaleString('ru-RU'))}</p></div></div>`).join('')}</div></section>`}
function accounts(){return`<div class="toolbar"><span class="small muted">Роли выдаёт администратор. Самостоятельной регистрации нет.</span><span class="spacer"></span>${button('Создать аккаунт','account',{},'primary','plus')}</div><section class="panel"><div class="table-scroll"><table class="table"><thead><tr><th>ИМЯ / ЛОГИН</th><th>РОЛЬ</th><th>ПРИВЯЗКА</th><th>ДОСТУП</th><th></th></tr></thead><tbody><tr><td><strong>Администратор</strong><div class="subline">admin · основной аккаунт</div></td><td>Администратор</td><td>Всё пространство</td><td>${tag('Активен','green')}</td><td>${button('Пароль','password',{},'tiny')}</td></tr>${S.users.map(u=>`<tr><td><strong>${h(u.name)}</strong><div class="subline">${h(u.username)}</div></td><td>${h(ROLES[u.role])}</td><td>${h(u.role==='student'?name('groups',u.groupId)+' · '+u.subgroup:u.role==='teacher'?name('teachers',u.teacherId):'Всё пространство')}</td><td>${tag(u.active?'Активен':'Отключён',u.active?'green':'red')}</td><td>${button('Изменить','account',{id:u.id},'tiny','edit')}</td></tr>`).join('')}</tbody></table></div></section>`}
function guide(){return`<section class="panel guide"><h2>От одной пары до всей учебной недели</h2><p>UniFlow объединяет расписание, задания, объявления и согласование переносов. Учебные часы показываются по времени Казахстана. Автор проекта — Азат Араппаев.</p><h3>Попробовать роли за три минуты</h3><ol><li>Нажми «Демо ролей». Песочница работает отдельно от настоящего сайта.</li><li>Выбери «Администратор»: назначь преподавателя, измени аудиторию или добавь занятие.</li><li>Переключись на «Студент»: в расписании и уведомлениях появится результат.</li><li>Выбери «Преподаватель»: создай задание или запроси перенос своей пары.</li><li>Вернись к администратору и согласуй запрос. Расписание изменится только на выбранную дату.</li></ol><div class="table-scroll"><table><thead><tr><th>Роль</th><th>Что доступно</th></tr></thead><tbody><tr><td>Посетитель</td><td>Открытое расписание, справочники, объявления своей выбранной группы, экспорт календаря.</td></tr><tr><td>Студент</td><td>Своя группа и подгруппа, задания, личные отметки выполнения, уведомления и объявления группы.</td></tr><tr><td>Преподаватель</td><td>Собственные пары, задания и объявления учебным группам, запросы переносов, объявления своим группам.</td></tr><tr><td>Администратор</td><td>Назначения, справочники, аккаунты и роли, исключения по датам, решения по переносам, история и откат, импорт и экспорт.</td></tr></tbody></table></div><h3>Запустить настоящее пространство</h3><ol><li>Войди под логином <b>admin</b> и действующим админским паролем.</li><li>В справочниках добавь преподавателей и выбери их предметы. Затем создай группы и аудитории, если нужны дополнительные.</li><li>В расписании назначь занятиям преподавателей. Система не сохранит пересечение группы, преподавателя или аудитории.</li><li>В «Аккаунтах» создай логины студентов и преподавателей. Для преподавателя выбери его запись справочника, для студента — группу и подгруппу. Пароли передай участникам самостоятельно.</li><li>Объявления и изменения будут появляться внутри сайта у адресатов. При первом переходе с прежней версии обнови страницу.</li></ol><h3>Обычная пара или изменение по дате?</h3><p>«Изменить» редактирует регулярное занятие на все недели выбранного типа. «По дате» отменяет или переносит только одну встречу. Поддерживаются чётные и нечётные недели по номеру ISO-недели. Запрос преподавателя сам по себе ничего не меняет: требуется решение администратора.</p><h3>Безопасность и сохранение</h3><p>Реальную роль определяет сервер. Переключатель демо не выдаёт права на настоящем сайте. Пароль проверяется сервером; сессия действует два часа и хранится только в памяти вкладки. Отключение аккаунта прекращает его доступ. При одновременном редактировании устаревшие правки не перезапишут новые.</p><h3>Полезные инструменты</h3><ul><li>Поиск по предмету, преподавателю и аудитории; просмотр дня или недели.</li><li>«Найти свободную» в аудиториях — поиск свободного помещения на дату и время.</li><li>«Календарь .ics» — экспорт четырёх ближайших недель с учётом отмен и переносов.</li><li>«Печать» — версия расписания для бумаги или PDF.</li><li>JSON — резервная копия расписания. Перед импортом администратор видит количество записей и подтверждает замену.</li><li>В кабинете: тёмная тема, личные заметки, смена пароля и выход.</li></ul><h3>Границы беты</h3><p>Уведомления доставляются внутри сайта. SMS, WhatsApp, email и фоновые push-уведомления не подключены. Отметка задания означает личный прогресс, а не загрузку работы. Офлайн доступен только сохранённый демо-пример; настоящее редактирование требует интернета. Демо-преподаватели и студенты вымышлены. В настоящем расписании неизвестные преподаватели оставлены неназначенными.</p><div class="row section-space">${button('Попробовать студента','demoRole',{role:'student'},'primary','users')}${button('Попробовать преподавателя','demoRole',{role:'teacher'},'','users')}${button('Попробовать администратора','demoRole',{role:'admin'},'','users')}<a class="btn" href="https://github.com/xan-xz/schedule" target="_blank" rel="noopener">GitHub проекта</a></div></section>`}
function render(){if(!S.data){$('app').innerHTML=shell(`<section class="panel"><div class="empty">${S.online?'Загружаем данные…':'Подключаем учебное пространство…'}<div class="row section-space" style="justify-content:center">${button('Повторить','refresh',{},'')}${S.base?button('Открыть демо','demo',{},'primary'):''}</div></div></section>`);return}if(!allowedPage(S.page))S.page='overview';const pages={overview:dashboard,schedule,tasks,notifications,requests,attendance,catalogs,history:historyPage,accounts,guide};const search=document.activeElement?.id==='global-search',pos=search?document.activeElement.selectionStart:null;$('app').innerHTML=shell(pages[S.page]());if(search){$('global-search').focus();if(pos!==null)$('global-search').setSelectionRange(pos,pos)}}
function closeModal(){$('modal').close();$('modal').innerHTML='';$('modal').dataset.revision=''}
function showForm(title,fields,onSubmit,submit='Сохранить',subtitle=''){
 const revision=S.revision;const field=f=>{const id='field-'+f.name;let input;if(f.type==='select')input=`<select name="${f.name}" id="${id}" ${f.required?'required':''}>${f.options.map(o=>`<option value="${h(o.value)}" ${o.value===String(f.value??'')?'selected':''}>${h(o.label)}</option>`).join('')}</select>`;else if(f.type==='checks')input=`<div class="checklist">${f.options.map(o=>`<label><input type="checkbox" name="${f.name}" value="${h(o.value)}" ${(f.value||[]).includes(o.value)?'checked':''}>${h(o.label)}</label>`).join('')}</div>`;else if(f.type==='textarea')input=`<textarea name="${f.name}" id="${id}" maxlength="${f.max||4000}" ${f.required?'required':''}>${h(f.value||'')}</textarea>`;else input=`<input name="${f.name}" id="${id}" type="${f.type||'text'}" value="${h(f.value??'')}" ${f.required?'required':''} ${f.min!==undefined?'min="'+f.min+'"':''} ${f.max!==undefined&&f.type==='number'?'max="'+f.max+'"':''} maxlength="${f.type==='password'?200:160}" ${f.type==='password'?'autocomplete="new-password"':''}>`;return`<label class="form-label ${f.full?'full':''}" for="${id}">${h(f.label)}${input}${f.help?`<small>${h(f.help)}</small>`:''}</label>`};
 $('modal').innerHTML=`<div class="dialog-head"><h2>${h(title)}</h2>${button('Закрыть','closeModal',{},'btn-square','close')}</div>${subtitle?`<p class="dialog-sub">${h(subtitle)}</p>`:''}<form id="dialog-form"><div class="form-grid">${fields.map(field).join('')}</div><div class="form-error" id="form-error" role="alert"></div><div class="form-actions">${button('Отмена','closeModal',{},'')}<button class="btn primary" type="submit">${h(submit)}</button></div></form>`;
 $('modal').dataset.revision=String(revision);$('modal').showModal();$('dialog-form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]');button.disabled=true;$('form-error').textContent='';try{const fd=new FormData(form),values=Object.fromEntries(fields.map(f=>[f.name,f.type==='checks'?fd.getAll(f.name):f.type==='number'?Number(fd.get(f.name)):String(fd.get(f.name)??'').trim()]));const keep=await onSubmit(values,revision);if(keep!==false)closeModal()}catch(error){$('form-error').textContent=error.message}finally{if(button.isConnected)button.disabled=false}};
}
