function announcementForm(){const groups=isTeacher()?S.data.groups.filter(g=>S.data.lessons.some(l=>l.teacherId===S.user.teacherId&&l.groupId===g.id)):S.data.groups;showForm('Новое объявление',[{name:'title',label:'Заголовок',required:true,full:true},{name:'body',label:'Сообщение',type:'textarea',required:true,full:true},selectField('groupId','Группа-получатель',groups,isTeacher()?groups[0]?.id:'',isAdmin()?'Без ограничения по группе':false),...(isAdmin()?[{name:'roles',label:'Кому показать',type:'checks',full:true,value:['student','teacher'],options:['student','teacher','admin'].map(value=>({value,label:ROLES[value]}))},selectField('teacherId','Конкретный преподаватель',S.data.teachers,'','Без ограничения')]:[])],async(v,rev)=>{if(isAdmin()&&!v.roles.length)throw Error('Выбери хотя бы одну роль');await act('announcement.save',{...v,roles:v.roles||['student']},rev)},'Опубликовать','Сообщение появится внутри сайта у указанных получателей. Внешние сообщения не отправляются.')}
