function catalogForm(entity,id){if(!isAdmin())throw Error('Нужны права администратора');const old=S.data[entity].find(x=>x.id===id);const labels={groups:'Группа',teachers:'Преподаватель',subjects:'Предмет',rooms:'Аудитория'};const fields=[{name:'name',label:'Название / имя',required:true,value:old?.name,full:true}];if(entity==='groups')fields.push({name:'subgroups',label:'Подгруппы через запятую',value:old?.subgroups.join(', ')||'А, Б',required:true,full:true});if(entity==='teachers')fields.push({name:'subjects',label:'Назначенные предметы',type:'checks',value:old?.subjects||[],options:S.data.subjects.map(s=>({value:s.id,label:s.name})),full:true});if(entity==='rooms')fields.push({name:'capacity',label:'Количество мест',type:'number',value:old?.capacity||30,min:1,max:500,required:true});showForm((old?'Изменить: ':'Добавить: ')+labels[entity],fields,async(v,rev)=>{if(entity==='groups')v.subgroups=[...new Set(v.subgroups.split(',').map(s=>s.trim()).filter(Boolean))];if(entity==='subjects')v.color='#7957d5';await act('catalog.save',{entity,item:{...v,...(old?{id:old.id}:{})}},rev)})}
function accountForm(id){const old=S.users.find(u=>u.id===id);showForm(old?'Изменить аккаунт':'Создать аккаунт',[{name:'name',label:'Имя пользователя',required:true,value:old?.name},{name:'username',label:'Логин',required:true,value:old?.username,help:'Латиница, цифры, точка, дефис. От 3 символов.'},{name:'role',label:'Роль',type:'select',value:old?.role||'student',options:['student','teacher','admin'].map(value=>({value,label:ROLES[value]}))},{name:'active',label:'Доступ',type:'select',value:old?.active===false?'false':'true',options:[{value:'true',label:'Активен'},{value:'false',label:'Отключён'}]},selectField('groupId','Группа студента',S.data.groups,old?.groupId||S.data.groups[0]?.id,false),{name:'subgroup',label:'Подгруппа студента',type:'select',value:old?.subgroup||'А',options:[...new Set(S.data.groups.flatMap(g=>g.subgroups))].map(value=>({value,label:value}))},selectField('teacherId','Запись преподавателя',S.data.teachers,old?.teacherId),{name:'password',label:old?'Новый пароль (пусто — не менять)':'Пароль',type:'password',required:!old,full:true,help:'От 8 символов. Передай пароль пользователю самостоятельно.'}],async(v)=>{v.active=v.active==='true';if(old)v.id=old.id;if(S.mode==='demo'){if(!/^[a-z0-9._-]{3,60}$/.test(v.username)||(!old&&v.password.length<8))throw Error('Проверь логин и пароль');if(S.demoUsers.some(u=>u.username===v.username&&u.id!==v.id))throw Error('Логин уже занят');delete v.password;v.id=v.id||uid();S.demoUsers=S.demoUsers.filter(u=>u.id!==v.id);S.demoUsers.push(v);applyDemo()}else{install(await api('account.save',{account:v}));render()}toast('Аккаунт сохранён')},'Сохранить аккаунт','Для студента обязательны группа и подгруппа; для преподавателя — его запись из справочника.')}
