function profile(){const notes=storage.get(myKey('notes'),'');$('modal').innerHTML=`<div class="dialog-head"><h2>Твой кабинет</h2>${button('Закрыть','closeModal',{},'btn-square','close')}</div><h3>${h(S.user.name)}</h3><p class="dialog-sub" style="margin:8px 0 20px">${h(ROLES[S.user.role])} · ${S.mode==='demo'?'демо-песочница':'настоящий аккаунт'}</p><div class="row">${button('Светлая / тёмная тема','theme',{},'','sun')}${S.user.role!=='guest'&&S.mode==='live'?button('Сменить пароль','password',{},'','edit')+button('Выйти из аккаунта','logout',{},'','logout'):''}</div><label class="form-label section-space">Личные заметки<textarea id="personal-notes" class="profile-notes" maxlength="10000" placeholder="Планы, вопросы к преподавателю, ссылки…">${h(notes)}</textarea><small>Сохраняются автоматически только в этом браузере для текущего профиля.</small></label><div class="notice-info section-space">${S.mode==='demo'?'Переключение ролей доступно вверху страницы. Для настоящего входа сначала выйди из демо.':'Роль выдаёт администратор. После перезагрузки вкладки потребуется войти заново.'}</div>`;$('modal').showModal()}
function passwordForm(){if(S.mode==='demo')throw Error('В демо паролей нет. Используй настоящий аккаунт.');showForm('Изменить пароль',[{name:'currentPassword',label:'Текущий пароль',type:'password',required:true,full:true},{name:'password',label:'Новый пароль (от 8 символов)',type:'password',required:true,full:true},{name:'repeat',label:'Повтори новый пароль',type:'password',required:true,full:true}],async v=>{if(v.password!==v.repeat)throw Error('Пароли не совпадают');if(v.password.length<8)throw Error('Минимум 8 символов');await api('password.change',v);S.token='';S.user={id:'guest',role:'guest',name:'Посетитель'};await refresh();toast('Пароль изменён. Войди с новым паролем.')},'Изменить и выйти','Все текущие сессии этого аккаунта будут завершены.')}
function freeRooms(){showForm('Найти свободную аудиторию',[{name:'date',label:'Дата',type:'date',value:S.date,required:true},{name:'capacity',label:'Минимум мест',type:'number',value:1,min:1,max:500},{name:'start',label:'Начало',type:'time',value:'12:00',required:true},{name:'end',label:'Конец',type:'time',value:'13:00',required:true}],async v=>{if(v.start>=v.end)throw Error('Конец должен быть позже начала');const busy=new Set(occurrences(S.data,v.date).filter(l=>!l.cancelled&&l.start<v.end&&l.end>v.start).map(l=>l.roomId));const rooms=S.data.rooms.filter(r=>r.capacity>=v.capacity&&!busy.has(r.id));let output=$('free-results');if(!output){output=document.createElement('div');output.id='free-results';output.className='notice-info section-space';$('dialog-form').append(output)}output.textContent=rooms.length?'Свободны: '+rooms.map(r=>r.name+' ('+r.capacity+' мест)').join(', '):'Свободных аудиторий с такими условиями нет';return false},'Найти','Поиск учитывает регулярное расписание, тип недели, отмены и переносы.')}
function download(filename,text,mime){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportJson(){const data=clone(S.mode==='demo'?S.demoFull:S.data);const allowed=Object.fromEntries(['groups','teachers','subjects','rooms','lessons','exceptions'].map(k=>[k,data[k]]));download('uniflow-schedule.json',JSON.stringify({format:'uniflow-2',exportedAt:new Date().toISOString(),...allowed},null,2),'application/json')}
function importJson(){if(!isAdmin())throw Error('Нужны права администратора');const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file)return;if(file.size>1000000)throw Error('Размер файла не должен превышать 1 МБ');const data=JSON.parse(await file.text());if(data.format!=='uniflow-2')throw Error('Нужен файл экспорта UniFlow 2');const full=clone(S.mode==='demo'?S.demoFull:S.data);for(const k of ['groups','subjects','teachers','rooms','lessons','exceptions'])full[k]=data[k];validate(full);showForm('Подтвердить импорт',[],async(_,rev)=>act('import',{data},rev),'Заменить расписание',data.groups.length+' групп, '+data.lessons.length+' занятий. Текущие назначения будут заменены. Предыдущая версия останется в истории.')}catch(e){toast(e.message)}};input.click()}
function icsEscape(s){return String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function exportIcs(){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//UniFlow//Schedule//RU','CALSCALE:GREGORIAN'];for(let n=0;n<28;n++){const date=addDays(localDate(),n);for(const l of scopedLessons(date).filter(l=>!l.cancelled)){const stamp=t=>new Date(date+'T'+t+':00+05:00').toISOString().replace(/[-:]/g,'').replace('.000','');lines.push('BEGIN:VEVENT','UID:'+l.id+'-'+date+'@uniflow','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART:'+stamp(l.start),'DTEND:'+stamp(l.end),'SUMMARY:'+icsEscape(name('subjects',l.subjectId)),'LOCATION:'+icsEscape(name('rooms',l.roomId,'')),'DESCRIPTION:'+icsEscape(name('groups',l.groupId)+' · '+name('teachers',l.teacherId,'')),'END:VEVENT')}}lines.push('END:VCALENDAR');download('uniflow.ics',lines.join('\r\n')+'\r\n','text/calendar;charset=utf-8');toast('Экспортированы ближайшие 28 дней по текущему фильтру')}
function attendanceCsv(){const rows=[['Дата','Предмет','Студент','Отметка'],...S.data.attendance.map(a=>[a.date,name('subjects',S.data.lessons.find(l=>l.id===a.lessonId)?.subjectId),S.users.find(u=>u.id===a.studentId)?.name||a.studentId,attStatus(a.status)])];const safe=v=>{let s=String(v);if(/^[=+@-]/.test(s))s="'"+s;return'"'+s.replace(/"/g,'""')+'"'};download('uniflow-attendance.csv','\ufeff'+rows.map(row=>row.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
async function rollback(revision){showForm('Восстановить версию '+revision,[],async()=>{if(S.mode==='demo'){const snapshot=S.versions.find(v=>v.revision===revision);if(!snapshot)throw Error('Версия не найдена');const before=clone(S.demoFull);S.demoFull=clone(snapshot.data);validate(S.demoFull);S.versions.unshift({revision:S.revision,data:before,actor:S.user.name,reason:'Откат к версии '+revision,created_at:new Date().toISOString()});S.revision++;applyDemo()}else{install(await api('rollback',{revision:S.revision,target:revision}));render()}toast('Версия восстановлена')},'Восстановить','Текущие расписание, задания, объявления и журнал будут заменены. Текущая версия тоже сохранится для отката.')}
async function handleAction(action,args,el){
 if(action==='page'){S.page=args.page;S.search='';render();return}if(action==='closeModal'){closeModal();return}if(action==='demo'){await enterDemo();return}if(action==='leaveDemo'){await leaveDemo();return}if(action==='demoRole'){const role=args.role||el?.dataset.role;if(S.mode!=='demo')await enterDemo(role);else{S.user=clone(S.demoUsers.find(u=>u.id===({student:'demo-student-a',teacher:'demo-teacher',admin:'demo-admin'}[role]))||DEMO_USERS[0]);S.scope='group';S.teacherId='';S.page='overview';S.search='';applyDemo();history.replaceState(null,'',location.pathname+'?demo='+role)}return}
 if(action==='resetDemo'){showForm('Сбросить демо',[],async()=>{storage.set('uf.demo',null);await enterDemo(S.user.role)},'Сбросить','Все изменения в песочнице будут удалены. Настоящий сайт не изменится.');return}
 if(action==='refresh'){await refresh();return}if(action==='day'){S.date=el?.dataset.date||args.date;S.weekView=false;render();return}if(action==='week'){S.date=addDays(S.date,args.offset);render();return}if(action==='today'){S.date=localDate();render();return}if(action==='toggleWeek'){S.weekView=!S.weekView;render();return}if(action==='taskFilter'){S.taskFilter=el.dataset.value;render();return}if(action==='catalogTab'){S.catalog=el.dataset.kind;render();return}
 if(action==='login'){loginForm();return}if(action==='profile'){profile();return}if(action==='password'){passwordForm();return}if(action==='theme'){document.body.classList.toggle('dark');storage.set('uf.dark',document.body.classList.contains('dark'));return}if(action==='logout'){try{await api('logout')}catch{}S.token='';S.user={id:'guest',role:'guest',name:'Посетитель'};S.scope='group';S.teacherId='';closeModal();await refresh();toast('Выход выполнен');return}
 if(action==='lesson'){lessonForm(args.id);return}if(action==='exception'){exceptionForm(args.id,args.date);return}if(action==='task'){taskForm(args.id);return}if(action==='request'){requestForm(args.id,args.date);return}if(action==='announcement'){announcementForm();return}if(action==='catalog'){catalogForm(args.entity,args.id);return}if(action==='account'){accountForm(args.id);return}if(action==='freeRooms'){freeRooms();return}
 if(action==='deleteLesson'){showForm('Удалить регулярное занятие',[],async(_,rev)=>{await act('lesson.delete',{id:args.id},rev)},'Удалить занятие','Будут удалены связанные исключения по датам, запросы и записи посещаемости. Предыдущая версия останется в истории.');return}if(action==='removeException'){await act('exception.delete',{lessonId:args.id,date:args.date});closeModal();return}if(action==='deleteTask'){showForm('Удалить задание',[],async(_,rev)=>act('task.delete',{id:args.id},rev),'Удалить','Задание исчезнет у получателей.');return}if(action==='deleteCatalog'){showForm('Удалить запись справочника',[],async(_,rev)=>act('catalog.delete',args,rev),'Удалить','Если запись используется в занятиях или аккаунтах, удаление будет запрещено.');return}
 if(action==='decide'){showForm(args.status==='approved'?'Согласовать перенос':'Отклонить перенос',[{name:'response',label:'Комментарий преподавателю',type:'textarea',full:true}],async(v,rev)=>act('request.decide',{...args,...v},rev),args.status==='approved'?'Согласовать':'Отклонить','При согласовании проверяются все пересечения на выбранную дату.');return}
 if(action==='read'||action==='readAll'){const read=new Set(storage.get(myKey('read'),[]));if(action==='read')read.add(args.id);else S.data.announcements.forEach(n=>read.add(n.id));storage.set(myKey('read'),[...read]);render();return}
 if(action==='exportJson'){exportJson();return}if(action==='import'){importJson();return}if(action==='exportIcs'){exportIcs();return}if(action==='attendanceCsv'){attendanceCsv();return}if(action==='print'){window.print();return}if(action==='share'){const url=new URL(location.href);url.search='';url.searchParams.set('group',S.groupId);url.searchParams.set('subgroup',S.subgroup);url.searchParams.set('date',S.date);await navigator.clipboard.writeText(url.toString());toast('Ссылка на выбранную группу скопирована');return}if(action==='rollback'){rollback(args.revision);return}
}
document.addEventListener('click',event=>{const nav=event.target.closest('[data-page]');if(nav){S.page=nav.dataset.page;S.search='';render();window.scrollTo({top:0,behavior:'smooth'});return}const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();let args={};try{args=JSON.parse(decodeURIComponent(el.dataset.args||'%7B%7D'))}catch{}handleAction(el.dataset.action,args,el).catch(e=>toast(e.message))});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.dataset.filter){S[el.dataset.filter]=el.value;if(el.dataset.filter==='groupId'){S.subgroup=S.data.groups.find(g=>g.id===S.groupId)?.subgroups[0]||'А';storage.set('uf.group',S.groupId)}if(el.dataset.filter==='subgroup')storage.set('uf.subgroup',S.subgroup);if(S.mode==='live'&&S.user.role==='guest')await refresh(true);else render()}if(el.dataset.taskCheck){const done=new Set(storage.get(myKey('tasks'),[]));el.checked?done.add(el.dataset.taskCheck):done.delete(el.dataset.taskCheck);storage.set(myKey('tasks'),[...done]);render()}if(el.id==='attendance-date'){S.date=el.value;render()}if(el.id==='attendance-lesson'){S.attendanceId=el.value;render()}if(el.dataset.attendance&&el.value){el.disabled=true;await act('attendance.save',{studentId:el.dataset.attendance,lessonId:S.attendanceId,date:S.date,status:el.value});}}catch(e){toast(e.message);render()}});
document.addEventListener('input',event=>{if(event.target.id==='global-search'){S.search=event.target.value;S.page='schedule';S.weekView=false;render()}if(event.target.id==='personal-notes')storage.set(myKey('notes'),event.target.value)});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();$('global-search')?.focus()}if(event.key==='Enter'&&event.target.matches('.week-lesson'))event.target.click()});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh(true)});window.addEventListener('online',()=>refresh(true));window.addEventListener('storage',event=>{if(event.key==='uf.demo'&&S.mode==='demo'){const saved=storage.get('uf.demo',null);if(saved&&saved.revision>S.revision){S.demoFull=saved.data;S.demoUsers=saved.users;S.revision=saved.revision;S.versions=saved.versions;install({data:visible(S.demoFull,S.user),revision:S.revision,user:S.user,users:isAdmin()?S.demoUsers:isTeacher()?S.demoUsers.filter(u=>u.role==='student'):[],versions:S.versions});render()}}});
setInterval(()=>refresh(true),20000);setInterval(()=>{if(!document.hidden&&!$('modal').open&&S.page==='overview'&&S.data)render()},60000);
if(storage.get('uf.dark',false))document.body.classList.add('dark');
