render();try{const response=await fetch(new URL('./seed.json',import.meta.url));if(response.ok)S.base=await response.json()}catch{}
if(['student','teacher','admin'].includes(query.get('demo'))){await enterDemo(query.get('demo'))}else{await refresh()}
connectRealtime();
